CREATE TABLE permissions (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, code VARCHAR(191) NOT NULL, name TEXT NOT NULL, resource_type VARCHAR(191) NOT NULL, action VARCHAR(191) NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'active', version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by VARCHAR(255) NOT NULL, updated_by VARCHAR(255) NOT NULL, UNIQUE KEY uq_permissions_tenant_code (tenant_id, code), UNIQUE KEY uq_permissions_resource_action (tenant_id, resource_type, action)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE roles (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, code VARCHAR(191) NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL, data_scope VARCHAR(32) NOT NULL DEFAULT 'tenant', status VARCHAR(32) NOT NULL DEFAULT 'active', version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by VARCHAR(255) NOT NULL, updated_by VARCHAR(255) NOT NULL, UNIQUE KEY uq_roles_tenant_code (tenant_id, code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE role_permissions (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, role_id VARCHAR(36) NOT NULL, permission_id VARCHAR(36) NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'active', version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by VARCHAR(255) NOT NULL, updated_by VARCHAR(255) NOT NULL, UNIQUE KEY uq_role_permissions (role_id, permission_id), CONSTRAINT fk_role_permissions_role FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE, CONSTRAINT fk_role_permissions_permission FOREIGN KEY (permission_id) REFERENCES permissions(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE role_bindings (id VARCHAR(36) PRIMARY KEY, tenant_id VARCHAR(36) NOT NULL, subject_id VARCHAR(191) NOT NULL, subject_type VARCHAR(32) NOT NULL, role_id VARCHAR(36) NOT NULL, organization_unit_id VARCHAR(36), status VARCHAR(32) NOT NULL DEFAULT 'active', version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by VARCHAR(255) NOT NULL, updated_by VARCHAR(255) NOT NULL, INDEX idx_role_bindings_subject (tenant_id, subject_type, subject_id, status), CONSTRAINT fk_role_bindings_role FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE authorization_policy_versions (tenant_id VARCHAR(36) PRIMARY KEY, policy_version BIGINT NOT NULL DEFAULT 1, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by VARCHAR(255) NOT NULL, updated_by VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE authorization_subject_groups (tenant_id VARCHAR(36) NOT NULL, membership_id VARCHAR(36) NOT NULL, group_id VARCHAR(36) NOT NULL, status VARCHAR(32) NOT NULL, source_occurred_at DATETIME(6) NOT NULL, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by VARCHAR(255) NOT NULL, updated_by VARCHAR(255) NOT NULL, PRIMARY KEY (tenant_id, membership_id, group_id), INDEX idx_authorization_subject_groups_active (tenant_id, membership_id, status, group_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE authorization_processed_events (event_id VARCHAR(64) PRIMARY KEY, event_type VARCHAR(255) NOT NULL, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by VARCHAR(255) NOT NULL, updated_by VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE authorization_outbox_events (id VARCHAR(36) PRIMARY KEY, subject VARCHAR(255) NOT NULL, envelope LONGBLOB NOT NULL, attempts INT NOT NULL DEFAULT 0, available_at DATETIME(6) NOT NULL, published_at DATETIME(6), last_error TEXT NOT NULL, version BIGINT NOT NULL DEFAULT 1, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, created_by VARCHAR(255) NOT NULL, updated_by VARCHAR(255) NOT NULL, INDEX idx_authorization_outbox_pending (published_at, available_at, created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
